-- ----------------------------
-- Table structure for `lt_betting_records`
-- ----------------------------
DROP TABLE IF EXISTS `lt_betting_records`;
CREATE TABLE `lt_betting_records` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `codes` varchar(255) DEFAULT NULL COMMENT '投注号码',
  `account` varchar(255) DEFAULT NULL,
  `playway` tinyint(4) DEFAULT '10' COMMENT '投注方式：10定位胆',
  `playway_name` varchar(32) DEFAULT NULL COMMENT '投注方式',
  `betting_money` decimal(11,2) DEFAULT '0.00' COMMENT '投注金额',
  `bonus` decimal(11,2) DEFAULT '0.00' COMMENT '中奖金额',
  `single` float DEFAULT NULL COMMENT '倍数(元)',
  `profits` decimal(11,2) DEFAULT NULL COMMENT '利润',
  `qihao` varchar(20) DEFAULT NULL COMMENT '期号',
  `kj_codes` varchar(24) DEFAULT NULL COMMENT '开奖号码',
  `position` varchar(10) DEFAULT '1,3' COMMENT '定位位置',
  `status` tinyint(4) DEFAULT '0' COMMENT '中奖状态：0:正常、1:中奖、2:未中奖',
  `sn` varchar(255) DEFAULT NULL COMMENT '方案号',
  `snid` varchar(24) DEFAULT NULL COMMENT '订单号',
  `plan_id` int(11) DEFAULT NULL COMMENT '计划id',
  `is_simulate` tinyint(4) DEFAULT '1' COMMENT '是否模拟投注',
  `lotteryclass` varchar(10) DEFAULT 'ssc' COMMENT '彩种',
  `createtime` int(11) DEFAULT NULL,
  `create_time` varchar(32) DEFAULT NULL COMMENT '投注时间',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  `created_at` int(11) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `account` (`account`) USING BTREE,
  KEY `snid` (`snid`),
  KEY `sn` (`sn`)
) ENGINE=MyISAM AUTO_INCREMENT=1378 DEFAULT CHARSET=utf8 COMMENT='用户追号记录表';

-- ----------------------------
-- Records of lt_betting_records
-- ----------------------------
INSERT INTO `lt_betting_records` VALUES ('150', '0,X,X,9@9,X,X,0@1,X,X,8@8,X,X,1@2,X,X,7@7,X,X,2@3,X,X,6@6,X,X,3@4,X,X,5@5,X,X,4', 'gaozi2017', '1', '两字定', '2.00', '0.00', '0.2', '-2.00', '180605074', '3,6,5,3,6', '1,4', '1', null, null, null, '0', 'ssc', '1528193522', '2018-06-05 18:12:02', null, null);

-- ----------------------------
-- Table structure for `lt_code_daily_tend`
-- ----------------------------
DROP TABLE IF EXISTS `lt_code_daily_tend`;
CREATE TABLE `lt_code_daily_tend` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(32) DEFAULT NULL COMMENT '用户账号',
  `count` varchar(32) DEFAULT NULL COMMENT '开奖期号',
  `date` varchar(4) DEFAULT '1' COMMENT '是否正常追号',
  PRIMARY KEY (`id`),
  KEY `account` (`code`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='用户追号记录表';

