-- ----------------------------
-- Table structure for `lt_qx_three_num_trend`
-- ----------------------------
DROP TABLE IF EXISTS `lt_qx_three_num_trend`;
CREATE TABLE `lt_qx_three_num_trend` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `kj_code` varchar(8) DEFAULT NULL COMMENT '号码',
  `tz_type` int(11) DEFAULT NULL COMMENT '投注类型 1:三字现 2:定位胆',
  `issue` int(11) DEFAULT NULL COMMENT '期号',
  `date` date DEFAULT NULL COMMENT '开奖日期',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`kj_code`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='三字现开奖记录表';

-- ----------------------------
-- Records of lt_qx_three_num_trend
-- ----------------------------

-- ----------------------------
-- Table structure for `lt_qxc_kj_data`
-- ----------------------------
DROP TABLE IF EXISTS `lt_qxc_kj_data`;
CREATE TABLE `lt_qxc_kj_data` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `kj_code` varchar(4) DEFAULT NULL COMMENT '开奖号码，4位',
  `kj_7code` varchar(7) DEFAULT NULL COMMENT '开奖号码7位',
  `qihao` int(11) DEFAULT NULL COMMENT '期号',
  `date_time` datetime DEFAULT NULL COMMENT '开奖日期',
  `time` int(11) NOT NULL COMMENT '开奖时间戳',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `qihao` (`qihao`) USING BTREE,
  KEY `date_time` (`date_time`)
) ENGINE=MyISAM AUTO_INCREMENT=49 DEFAULT CHARSET=utf8 COMMENT='七星彩开奖数据记录表';

