-- Table structure for `lt_ssc_dw_hz_copy`
-- ----------------------------
DROP TABLE IF EXISTS `lt_ssc_dw_hz_copy`;
CREATE TABLE `lt_ssc_dw_hz_copy` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `positions` varchar(8) DEFAULT NULL COMMENT '开奖号码str',
  `qihao` varchar(11) DEFAULT NULL COMMENT '当前期号',
  `periods` tinyint(4) DEFAULT NULL COMMENT '近多少期，20，50，100，150，200，300，500，1000，2000期',
  `current_miss` tinyint(1) DEFAULT NULL COMMENT '当前遗漏',
  `last_time_miss` tinyint(4) DEFAULT NULL COMMENT '上次遗漏',
  `hz_0` tinyint(1) DEFAULT NULL COMMENT '0',
  `hz_1` tinyint(1) DEFAULT NULL COMMENT '1',
  `hz_2` tinyint(1) DEFAULT NULL COMMENT '2',
  `hz_3` tinyint(1) DEFAULT NULL COMMENT '3',
  `hz_4` tinyint(1) DEFAULT NULL COMMENT '4',
  `hz_5` tinyint(1) DEFAULT NULL COMMENT '5',
  `hz_6` tinyint(1) DEFAULT NULL COMMENT '6',
  `hz_7` tinyint(1) DEFAULT NULL COMMENT '7',
  `hz_8` tinyint(1) DEFAULT NULL COMMENT '8',
  `hz_9` tinyint(1) DEFAULT NULL COMMENT '8',
  `hz_10` tinyint(1) DEFAULT NULL COMMENT '10',
  `hz_11` tinyint(1) DEFAULT NULL COMMENT '11',
  `hz_12` tinyint(1) DEFAULT NULL COMMENT '12',
  `hz_13` tinyint(1) DEFAULT NULL COMMENT '13',
  `hz_14` tinyint(1) DEFAULT NULL COMMENT '14',
  `hz_15` tinyint(1) DEFAULT NULL COMMENT '15',
  `hz_16` tinyint(1) DEFAULT NULL COMMENT '16',
  `hz_17` tinyint(1) DEFAULT NULL COMMENT '17',
  `hz_18` tinyint(1) DEFAULT NULL COMMENT '18',
  PRIMARY KEY (`id`),
  KEY `hz_0` (`hz_0`),
  KEY `hz_1` (`hz_1`),
  KEY `hz_2` (`hz_2`),
  KEY `hz_3` (`hz_3`),
  KEY `hz_4` (`hz_4`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COMMENT='二字定和值遗漏表';

