-- Table structure for `lt_ssc_dw_hz_static`
-- ----------------------------
DROP TABLE IF EXISTS `lt_ssc_dw_hz_static`;
CREATE TABLE `lt_ssc_dw_hz_static` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `positions` varchar(8) DEFAULT NULL COMMENT '位置，1,2;1,3;1:4;2,3;2,4;3,4',
  `qihao` varchar(11) DEFAULT NULL COMMENT '当前期号',
  `periods` smallint(4) DEFAULT NULL COMMENT '近多少期，20，50，100，150，200，300，500，1000，2000期',
  `hz_0` smallint(4) DEFAULT '0' COMMENT '0',
  `hz_1` smallint(4) DEFAULT '0',
  `hz_2` smallint(4) DEFAULT '0' COMMENT '2',
  `hz_3` smallint(4) DEFAULT '0' COMMENT '3',
  `hz_4` smallint(4) DEFAULT '0' COMMENT '4',
  `hz_5` smallint(4) DEFAULT '0' COMMENT '5',
  `hz_6` smallint(4) DEFAULT '0' COMMENT '6',
  `hz_7` smallint(4) DEFAULT '0' COMMENT '7',
  `hz_8` smallint(4) DEFAULT '0' COMMENT '8',
  `hz_9` smallint(4) DEFAULT '0' COMMENT '9',
  `hz_10` smallint(4) DEFAULT '0' COMMENT '10',
  `hz_11` smallint(4) DEFAULT '0' COMMENT '11',
  `hz_12` smallint(4) DEFAULT '0' COMMENT '12',
  `hz_13` smallint(4) DEFAULT '0' COMMENT '13',
  `hz_14` smallint(4) DEFAULT '0' COMMENT '14',
  `hz_15` smallint(4) DEFAULT '0' COMMENT '15',
  `hz_16` smallint(4) DEFAULT '0' COMMENT '16',
  `hz_17` smallint(4) DEFAULT '0' COMMENT '17',
  `hz_18` smallint(4) DEFAULT '0' COMMENT '18',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `positions` (`positions`),
  KEY `periods` (`periods`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8 COMMENT='二字定和值统计表';

