-- ----------------------------
-- Table structure for `lt_ssc_kj_data`
-- ----------------------------
DROP TABLE IF EXISTS `lt_ssc_kj_data`;
CREATE TABLE `lt_ssc_kj_data` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `kj_code` varchar(8) DEFAULT NULL COMMENT '开奖号码',
  `code_str` varchar(24) DEFAULT NULL COMMENT '开奖号码str',
  `code1` tinyint(4) DEFAULT NULL COMMENT '万位',
  `code2` tinyint(4) DEFAULT NULL COMMENT '千位',
  `code3` tinyint(4) DEFAULT NULL COMMENT '百位',
  `code4` tinyint(4) DEFAULT NULL COMMENT '十位',
  `code5` tinyint(4) DEFAULT NULL COMMENT '个位',
  `code_1_2` tinyint(4) DEFAULT NULL COMMENT '1、2位和值',
  `code_1_3` tinyint(4) DEFAULT NULL COMMENT '1、3位和值',
  `code_1_4` tinyint(4) DEFAULT NULL COMMENT '1、4位和值',
  `code_2_3` tinyint(4) DEFAULT NULL COMMENT '2、3位和值',
  `code_2_4` tinyint(4) DEFAULT NULL COMMENT '2、4位和值',
  `code_3_4` tinyint(4) DEFAULT NULL COMMENT '3、4位和值',
  `qihao` int(11) DEFAULT NULL COMMENT '期号',
  `date` date DEFAULT NULL COMMENT '开奖日期',
  `created_at` int(11) DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` int(11) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `qihao` (`qihao`) USING BTREE,
  KEY `date` (`date`),
  KEY `code1` (`code1`),
  KEY `code2` (`code2`),
  KEY `code3` (`code3`),
  KEY `code4` (`code4`),
  KEY `code5` (`code5`),
  KEY `code_1_2` (`code_1_2`),
  KEY `code_1_3` (`code_1_3`),
  KEY `code_1_4` (`code_1_4`),
  KEY `code_2_3` (`code_2_3`),
  KEY `code_2_4` (`code_2_4`),
  KEY `code_3_4` (`code_3_4`)
) ENGINE=MyISAM AUTO_INCREMENT=21654 DEFAULT CHARSET=utf8 COMMENT='时时彩开奖数据记录表';

