-- ----------------------------
-- Table structure for `lt_user`
-- ----------------------------
DROP TABLE IF EXISTS `lt_user`;
CREATE TABLE `lt_user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `admin_id` tinyint(4) DEFAULT NULL COMMENT '管理员id',
  `username` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '临时账号名',
  `account` varchar(255) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '投注账号',
  `balance` decimal(10,2) DEFAULT NULL COMMENT '用户余额',
  `simulate_balance` decimal(10,2) DEFAULT NULL,
  `email` varchar(255) COLLATE utf8_unicode_ci NOT NULL,
  `tz_password` varchar(20) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '网盘密码',
  `ssc_domain` varchar(32) COLLATE utf8_unicode_ci DEFAULT 'https://700056.com' COMMENT '网盘地址',
  `cookie` varchar(64) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT '登陆cookie',
  `cookie2` varchar(64) COLLATE utf8_unicode_ci DEFAULT NULL,
  `status` smallint(6) NOT NULL DEFAULT '1' COMMENT '状态',
  `created_at` int(11) NOT NULL,
  `updated_at` int(11) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci COMMENT='彩票用户表';

